import React, { useState, useEffect } from 'react';
import { api } from './services/api';
import Navbar from './components/Navbar';
import Login from './components/Login';
import Register from './components/Register';
import Disponibilidad from './components/Disponibilidad';
import MisReservas from './components/MisReservas';

import PanelProfesor from './components/PanelProfesor';

function App() {
  const [currentView, setCurrentView] = useState('login');
  const [usuario, setUsuario] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    verificarSesion();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const verificarSesion = async () => {
    try {
      const response = await api.get('/usuarios/session');
      if (response.data.success) {
        const userData = response.data.data;
        setUsuario(userData);
        setCurrentView(userData.rol === 'PROFESOR' ? 'profesor' : 'disponibilidad');
      }
    } catch (error) {
      console.log('No hay sesión activa');
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = (usuarioData) => {
    setUsuario(usuarioData);
    setCurrentView(usuarioData.rol === 'PROFESOR' ? 'profesor' : 'disponibilidad');
  };

  const handleLogout = async () => {
    try {
      await api.post('/usuarios/logout');
      setUsuario(null);
      setCurrentView('login');
    } catch (error) {
      console.error('Error al cerrar sesión:', error);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-purple-600 via-blue-600 to-cyan-500">
        <div className="text-center animate-fadeIn">
          <div className="animate-spin rounded-full h-20 w-20 border-4 border-white border-t-transparent mx-auto"></div>
          <p className="mt-6 text-white text-xl font-bold">Cargando...</p>
        </div>
      </div>
    );
  }

  if (!usuario) {
    return (
      <div className="min-h-screen">
        {currentView === 'login' ? (
          <Login 
            onLogin={handleLogin}
            onSwitchToRegister={() => setCurrentView('register')}
          />
        ) : (
          <Register 
            onRegister={() => setCurrentView('login')}
            onSwitchToLogin={() => setCurrentView('login')}
          />
        )}
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col">
      <Navbar 
        currentView={currentView}
        setCurrentView={setCurrentView}
        usuario={usuario}
        onLogout={handleLogout}
      />

      <main className="flex-grow container mx-auto px-6 py-10">
        {currentView === 'disponibilidad' && (
          <Disponibilidad usuario={usuario} />
        )}

        {currentView === 'mis-reservas' && (
          <MisReservas usuario={usuario} />
        )}

        {currentView === 'profesor' && usuario.rol === 'PROFESOR' && (
          <PanelProfesor usuario={usuario} />
        )}
      </main>

      <footer className="bg-gradient-to-r from-purple-600 via-blue-600 to-cyan-600 border-t-4 border-white/20 mt-16">
        <div className="container mx-auto px-6 py-8 text-center text-white">
          <div className="flex items-center justify-center space-x-3 mb-3">
            <span className="text-3xl">🖥️</span>
            <p className="text-lg font-bold">
              © 2025 Sistema de Gestión de Turnos - Laboratorio
            </p>
          </div>
          <p className="text-sm text-purple-100 font-medium">
            Universidad Cooperativa de Colombia - Proyecto Final Diseño de Software
          </p>
          <div className="mt-4 flex items-center justify-center space-x-2 text-xs text-purple-200">
            <span>✨</span>
            <span>Desarrollado con React & Spring Boot</span>
            <span>✨</span>
          </div>
        </div>
      </footer>
    </div>
  );
}

export default App;
